import java.util.Scanner;
import java.util.regex.MatchResult;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class CF_723B {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		String s = sc.next();


		String regex = "\\([a-zA-Z_]*\\)";
		Pattern pat = Pattern.compile(regex);
		Matcher mat = pat.matcher(s);

		String newString = mat.replaceAll("_");

		String[] left = newString.split("_+");
		int maxLength = 0;
		for(int i = 0;i<left.length;i++){
			maxLength = Math.max(maxLength,left[i].length());
		}

		System.out.println(maxLength);
		int count = 0;
		boolean isStart = false;
		int startIndex = -1;
		int endIndex = -1;
		for(int i = 0;i<s.length();i++){
			char c = s.charAt(i);
			if(c == '('){
				isStart = true;
				startIndex = i;
				continue;
			}
			if(isStart){
				if(c == ')'){
					isStart = false;
					endIndex = i;
					String tmp = s.substring(startIndex+1,endIndex);
					if(tmp.equals(""))
						continue;
					if(tmp.startsWith("_")){
						String[] tmps = tmp.split("_+");
						if(tmps.length!=0)
							count+=(tmps.length-1);
						else
							count+=tmps.length;
					}else{
						String[] tmps = tmp.split("_+");
						count+=tmps.length;
					}

				}
			}
		}
		System.out.println(count);
	}
}

